/* Pure link and file path detection for terminal rows; no DOM access. */
(() => {
  'use strict';
  // Where a URL ends follows UTS #58 (Unicode Link Detection), except that
  // CJK sentence punctuation, box drawing and backticks end it at once, and a
  // ? that starts an empty query is left out: terminal output puts prose,
  // frames and Markdown right after URLs.
  // Generated by scripts/gen-linkterm.cjs from Unicode 18.0 LinkTerm.txt and
  // LinkBracket.txt (Unicode License v3, see THIRD-PARTY-NOTICES.md).
  const LINK_TERM_RUNS = "";
  const LINK_BRACKETS = "()<>[]{}\u0f3a\u0f3b\u0f3c\u0f3d\u169b\u169c\u2045\u2046\u207d\u207e\u208d\u208e\u2308\u2309\u230a\u230b\u2768\u2769\u276a\u276b\u276c\u276d\u276e\u276f\u2770\u2771\u2772\u2773\u2774\u2775\u27c5\u27c6\u27e6\u27e7\u27e8\u27e9\u27ea\u27eb\u27ec\u27ed\u27ee\u27ef\u2983\u2984\u2985\u2986\u2987\u2988\u2989\u298a\u298b\u298c\u298f\u298e\u298d\u2990\u2991\u2992\u2993\u2994\u2995\u2996\u2997\u2998\u29d8\u29d9\u29da\u29db\u29fc\u29fd\u2e22\u2e23\u2e24\u2e25\u2e26\u2e27\u2e28\u2e29\u2e55\u2e56\u2e57\u2e58\u2e59\u2e5a\u2e5b\u2e5c\u2e62\u2e63\u3008\u3009\u300a\u300b\u300c\u300d\u300e\u300f\u3010\u3011\u3014\u3015\u3016\u3017\u3018\u3019\u301a\u301b\ufe59\ufe5a\ufe5b\ufe5c\ufe5d\ufe5e\uff08\uff09\uff3b\uff3d\uff5b\uff5d\uff5f\uff60\uff62\uff63";
  // End of generated data.
  const HARD = 0, INCLUDE = 1, SOFT = 2, OPEN = 3, CLOSE = 4;
  const runStart = [], runKind = [];
  {
    let at = 0;
    for (const m of LINK_TERM_RUNS.matchAll(/([HISOC])([0-9a-z]+)/g)) {
      runStart.push(at); runKind.push('HISOC'.indexOf(m[1])); at += parseInt(m[2], 36);
    }
  }
  const openOf = new Map();
  {
    const p = [...LINK_BRACKETS].map((c) => c.codePointAt(0));
    for (let i = 0; i < p.length; i += 2) openOf.set(p[i + 1], p[i]);
  }
  const STOPS = [0x60, 0x3001, 0x3002, 0xff01, 0xff0c, 0xff0e, 0xff1f];

  function linkTerm(cp) {
    if (STOPS.includes(cp) || (cp >= 0x2500 && cp <= 0x257f)) return HARD;
    let lo = 0, hi = runStart.length - 1;
    while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (runStart[mid] <= cp) lo = mid; else hi = mid - 1; }
    return runKind[lo];
  }

  // UTS #58's URL parts: what ends each one and what clears its brackets.
  const PARTS = {
    host: {end: ['/', '?', '#'], clear: []},
    path: {end: ['?', '#'], clear: ['/']},
    query: {end: ['#'], clear: ['=', '&']},
    fragment: {end: [':~:'], clear: []},
    directive: {end: [], clear: ['&', ',', ':~:']},
  };
  const STARTS = [['/', 'path'], ['?', 'query'], ['#', 'fragment'], [':~:', 'directive']];

  // The end of the URL whose host starts at text[i] (UTS #58's termination
  // algorithm, with the host as one more part).
  function urlEnd(text, i) {
    let safe = i, part = 'host', previous = '';
    const stack = [];
    const at = (s) => text.startsWith(s, i);
    while (i < text.length) {
      if (part && PARTS[part].end.some(at)) { previous = part; part = ''; }
      if (!part) {
        const start = STARTS.find(([s]) => at(s));
        if (!start || (start[1] === 'directive' && previous !== 'fragment' && previous !== 'directive')) return safe;
        part = start[1]; i += start[0].length; stack.length = 0;
        if (part !== 'query') safe = i;
        continue;
      }
      const clear = PARTS[part].clear.find(at);
      if (clear) { i += clear.length; safe = i; stack.length = 0; continue; }
      const cp = text.codePointAt(i);
      const next = i + (cp > 0xffff ? 2 : 1);
      switch (linkTerm(cp)) {
        case INCLUDE: break;
        case SOFT: i = next; continue;
        case OPEN: if (stack.length === 125) return safe; stack.push(cp); break;
        case CLOSE: if (stack.pop() !== openOf.get(cp)) return safe; break;
        default: return safe;
      }
      i = next; safe = i;
    }
    return safe;
  }

  // findURLs returns the http(s) URLs in text as [{url, index}].
  function findURLs(text) {
    const found = [];
    const re = /https?:\/\//g;
    for (let m; (m = re.exec(text));) {
      const end = urlEnd(text, re.lastIndex);
      if (end === re.lastIndex) continue;
      found.push({url: text.slice(m.index, end), index: m.index});
      re.lastIndex = end;
    }
    return found;
  }

  // A file path: absolute, ~/, or relative with a slash, in ASCII, with an
  // optional :LINE or :LINE:COL. Without ./, ../, ~/ or a leading /, a
  // relative path needs an extension with a letter or a line (not 1/2,
  // and/or, 2026/10/23), and an absolute one two names or an extension.
  // A slash, letter, digit, colon or @ before it is not a start (URLs,
  // host:path, @mentions).
  const PATH = /(?<![\w.+@%~\/:-])[\w.~\/-][\w.+@%~\/-]*(?::(\d+)(?::(\d+))?)?/g;
  const EXT = /\.[\w-]*[A-Za-z][\w-]*$/;

  // findPaths returns the file paths in text, outside its URLs, as
  // [{path, line, col, index, length}] (line and col 0 when not given).
  function findPaths(text, urls = findURLs(text)) {
    if (!text.includes('/')) return [];
    const spans = urls.map((u) => [u.index, u.index + u.url.length]);
    const found = [];
    for (const m of text.matchAll(PATH)) {
      const line = Number(m[1] || 0), col = Number(m[2] || 0);
      let path = m[1] ? m[0].slice(0, m[0].indexOf(':')) : m[0].replace(/\.+$/, '');
      if (!path.includes('/') || path.includes('//') || path.endsWith('/')) continue;
      if (spans.some(([a, b]) => m.index < b && m.index + m[0].length > a)) continue;
      if (path[0] === '~' && !path.startsWith('~/')) continue;
      const names = path.split('/').filter(Boolean);
      const last = names[names.length - 1];
      if (!last || last === '.' || last === '..') continue;
      const anchored = /^(~|\.{1,2})\//.test(path);
      if (path[0] === '/' ? names.length < 2 && !EXT.test(last) : !anchored && !EXT.test(last) && !line) continue;
      const length = m[1] ? m[0].length : path.length;
      found.push({path, line, col, index: m.index, length});
    }
    return found;
  }

  // findLinks returns the URLs and file paths (URLs only without paths) in
  // text as [{target, index, length}], in order; a path's target is
  // pathTarget's.
  function findLinks(text, paths = true) {
    const urls = findURLs(text);
    if (!paths) return urls.map((u) => ({target: u.url, index: u.index, length: u.url.length}));
    const found = findPaths(text, urls).map((p) => ({target: pathTarget(text.slice(p.index, p.index + p.length)), index: p.index, length: p.length}));
    return findLinks(text, false).concat(found).sort((a, b) => a.index - b.index);
  }

  // A path link's target: the text as printed, marked so that it is never
  // taken for a URL (pathOf reads it back).
  const PATH_MARK = 'iwato-path:';
  const pathTarget = (text) => PATH_MARK + text;
  const pathOf = (target) => typeof target === 'string' && target.startsWith(PATH_MARK) ? findPaths(target.slice(PATH_MARK.length))[0] || null : null;

  const FRAME = '│┃║|';

  // A row is {cells: [{c, x}], wrapped}: one entry per code unit with its
  // 0-based cell column (wide characters keep their first column).
  function lastContent(row) {
    let i = row.cells.length - 1;
    while (i >= 0 && row.cells[i].c === ' ') i--;
    return i;
  }

  // Applications such as Claude Code wrap long text themselves, so a URL that
  // runs into the right edge continues on the next row without the
  // terminal's own wrap flag. A right frame border plus one padding cell is allowed.
  function reachesEdge(row, cols) {
    let i = lastContent(row);
    if (i < 0) return false;
    if (FRAME.includes(row.cells[i].c)) {
      i--;
      if (i >= 0 && row.cells[i].c === ' ') i--;
      return i >= 0 && row.cells[i].c !== ' ' && row.cells[i].x >= cols - 4;
    }
    return row.cells[i].x >= cols - 2;
  }

  function rightBorder(row, cols) {
    const i = lastContent(row);
    return i >= 0 && FRAME.includes(row.cells[i].c) && row.cells[i].x >= cols - 3 ? i : -1;
  }

  // The logical line that starts at row i: its links and the row after it.
  // row(k) is the row k, undefined past the last; the line reads no row
  // before i and none past the one after it.
  function lineLinks(row, i, cols, firstY, paths) {
    // Build one logical line: text plus the cell/row of every code unit.
    let text = '';
    const pos = [];
    // A '|' that is a right border ends a URL, though '|' belongs to URLs elsewhere.
    const chars = (r, from) => {
      const border = row(r + 1)?.wrapped ? -1 : rightBorder(row(r), cols);
      return row(r).cells.slice(from).map((cell, k) => k + from === border ? '│' : cell.c);
    };
    const push = (r, from) => {
      const cells = row(r).cells, cs = chars(r, from);
      text += cs.join('');
      for (let k = 0; k < cs.length; k++) pos.push({x: cells[from + k].x, r});
    };
    push(i, 0);
    let j = i + 1;
    while (row(j)) {
      const prev = row(j - 1), cur = row(j);
      if (cur.wrapped) { text = text.replace(/ +$/, ''); pos.length = text.length; push(j, 0); j++; continue; }
      if (!reachesEdge(prev, cols)) break;
      // Join only when a URL (or the start of its scheme: the application
      // may break inside https://) ends at the edge and the next row
      // continues it into one URL.
      const before = text.replace(/[ │┃║|]+$/, '');
      const tail = /https?:\/\/\S*$|(?<![A-Za-z0-9])(?:https?(?::\/?)?|htt?|h)$/.test(before);
      let k = 0;
      while (k < cur.cells.length && (cur.cells[k].c === ' ' || FRAME.includes(cur.cells[k].c))) k++;
      if (!tail || k >= cur.cells.length || linkTerm((cur.cells[k].c + (cur.cells[k + 1]?.c || '')).codePointAt(0)) === HARD) break;
      const joined = before + chars(j, k).join('');
      if (!findURLs(joined).some((u) => u.index < before.length && u.index + u.url.length > before.length)) break;
      text = before; pos.length = before.length;
      push(j, k);
      j++;
    }
    const links = [];
    for (const {target, index, length} of paths || text.includes('://') ? findLinks(text, paths) : []) {
      const a = pos[index], b = pos[index + length - 1];
      links.push({url: target, start: {x: a.x + 1, y: firstY + a.r}, end: {x: b.x + 1, y: firstY + b.r}});
    }
    return {end: j, links};
  }

  // wrappedLinks returns [{url, start: {x, y}, end: {x, y}}] in 1-based,
  // inclusive cell coordinates (url is a path's target for a path; URLs
  // only without paths). rows[0] is buffer line firstY.
  function wrappedLinks(rows, cols, firstY, paths = true) {
    const links = [];
    for (let i = 0; i < rows.length;) {
      const line = lineLinks((k) => rows[k], i, cols, firstY, paths);
      links.push(...line.links);
      i = line.end;
    }
    return links;
  }

  const content = (c) => c.c !== ' ' && !FRAME.includes(c.c);

  // screenLines splits screen rows 0..n-1 (row(y) as for lineLinks) into
  // logical lines with the pieces of their URLs per row, 0-based cells:
  // [{start, end, pieces: [[y, [{from, to, url, group}]]]}]. Lines of old
  // (a previous result for as many rows and cols) are kept when none of
  // their rows nor the row after them is in dirty.
  function screenLines(row, n, cols, old, dirty) {
    const lines = [];
    let k = 0;
    for (let i = 0; i < n;) {
      while (old && k < old.length && old[k].start < i) k++;
      const o = old?.[k];
      if (o && o.start === i) {
        let y = i;
        while (y <= Math.min(o.end, n - 1) && !dirty.has(y)) y++;
        if (y > Math.min(o.end, n - 1)) { lines.push(o); i = o.end; continue; }
      }
      const {end, links} = lineLinks(row, i, cols, 0, false);
      const pieces = new Map();
      for (const link of links) {
        // Stable across redraws, so a hovered URL stays lit while the rest
        // of the screen changes.
        const group = link.start.y + ':' + link.start.x;
        for (let y = link.start.y; y <= link.end.y; y++) {
          const cells = row(y).cells;
          let from = y === link.start.y ? link.start.x - 1 : -1;
          let to = y === link.end.y ? link.end.x - 1 : -1;
          if (from < 0) { const first = cells.find(content); if (!first) continue; from = first.x; }
          if (to < 0) { const last = cells.findLast(content); if (!last) continue; to = last.x; }
          if (!pieces.has(y)) pieces.set(y, []);
          pieces.get(y).push({from, to, url: link.url, group});
        }
      }
      lines.push({start: i, end, pieces: [...pieces]});
      i = end;
    }
    return lines;
  }

  function safeURL(value) {
    if (typeof value !== 'string' || value.length > 4096 || /[\s\u0000-\u001f\u007f]/.test(value)) return '';
    try {
      const url = new URL(value);
      return (url.protocol === 'https:' || url.protocol === 'http:') && !url.username && !url.password ? url.href : '';
    } catch (_) { return ''; }
  }

  window.IwatoLinks = Object.freeze({findURLs, findPaths, findLinks, pathOf, wrappedLinks, screenLines, safeURL});
})();
